"use client";

import { useLayoutEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { Cpu, Compass, Workflow, Users, type LucideIcon } from "lucide-react";

gsap.registerPlugin(ScrollTrigger);

type Reason = {
  title: string;
  description: string;
  icon: LucideIcon;
  accent: string;
  side: "left" | "right";
  top: number; // vertical position within the pinned viewport, in %
};

const reasons: Reason[] = [
  {
    title: "Engineering depth",
    description:
      "We ship production AI, not prototypes — from model selection to deployment and everything in between.",
    icon: Cpu,
    accent: "#6E8CFF",
    side: "right",
    top: 10,
  },
  {
    title: "Built around you",
    description:
      "Every system is shaped by your data, your workflows and your goals. Never a template with your logo on it.",
    icon: Compass,
    accent: "#9B7CFF",
    side: "left",
    top: 37,
  },
  {
    title: "Agents that act",
    description:
      "Our AI doesn't just surface insight. It reasons, decides and executes the work that follows.",
    icon: Workflow,
    accent: "#57D6E0",
    side: "right",
    top: 64,
  },
  {
    title: "A partner past launch",
    description:
      "We stay close after go-live — tuning, monitoring and scaling the system as your business changes.",
    icon: Users,
    accent: "#4FE0B0",
    side: "left",
    top: 91,
  },
];

// Deterministic pseudo-random generator so server and client render
// identical particle positions (avoids hydration mismatch).
function seeded(i: number) {
  const x = Math.sin(i * 12.9898) * 43758.5453;
  return x - Math.floor(x);
}

const particles = Array.from({ length: 34 }, (_, i) => ({
  x: seeded(i) * 100,
  y: seeded(i + 100) * 100,
  size: 1 + seeded(i + 200) * 2.2,
  delay: seeded(i + 300) * 6,
  duration: 5 + seeded(i + 400) * 6,
}));

export default function WhyChooseUs() {
  const sectionRef = useRef<HTMLElement | null>(null);
  const pinRef = useRef<HTMLDivElement | null>(null);
  const headingRef = useRef<HTMLDivElement | null>(null);
  const lineInnerRef = useRef<HTMLDivElement | null>(null);
  const nodeRefs = useRef<(HTMLDivElement | null)[]>([]);
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
  const mobileCardRefs = useRef<(HTMLDivElement | null)[]>([]);
  const spotlightRef = useRef<HTMLDivElement | null>(null);

  useLayoutEffect(() => {
    const section = sectionRef.current;
    const pin = pinRef.current;
    if (!section || !pin) return;

    const reduceMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const ctx = gsap.context(() => {
      const cards = cardRefs.current.filter(Boolean) as HTMLDivElement[];
      const nodes = nodeRefs.current.filter(Boolean) as HTMLDivElement[];
      const mobileCards = mobileCardRefs.current.filter(
        Boolean
      ) as HTMLDivElement[];
      const lineInner = lineInnerRef.current;
      const heading = headingRef.current;

      if (reduceMotion) {
        gsap.set([cards, mobileCards, heading], { autoAlpha: 1, y: 0 });
        gsap.set(nodes, { scale: 1, autoAlpha: 1 });
        if (lineInner) gsap.set(lineInner, { scaleY: 1 });
        return;
      }

      /* ============================================================
         MOBILE / TABLET — simple staggered reveal, no pin
      ============================================================ */
      const mm = gsap.matchMedia();

      mm.add("(max-width: 1023px)", () => {
        gsap.set(mobileCards, { autoAlpha: 0, y: 50, force3D: true });

        mobileCards.forEach((card) => {
          gsap.to(card, {
            autoAlpha: 1,
            y: 0,
            duration: 0.8,
            ease: "power3.out",
            scrollTrigger: {
              trigger: card,
              start: "top 82%",
              toggleActions: "play none none reverse",
            },
          });
        });

        gsap.fromTo(
          ".wcu-mobile-track-fill",
          { scaleY: 0 },
          {
            scaleY: 1,
            ease: "none",
            transformOrigin: "top",
            scrollTrigger: {
              trigger: ".wcu-mobile-track",
              start: "top 75%",
              end: "bottom 60%",
              scrub: 0.6,
            },
          }
        );
      });

      /* ============================================================
         DESKTOP — pinned scrollytelling with thread + nodes
      ============================================================ */
      mm.add("(min-width: 1024px)", () => {
        if (!lineInner) return;

        gsap.set(heading, { autoAlpha: 1, y: 0 });
        gsap.set(cards, { autoAlpha: 0, y: 70, rotateY: 0, scale: 0.92, force3D: true });
        gsap.set(nodes, { scale: 0, autoAlpha: 0, force3D: true });
        gsap.set(lineInner, { scaleY: 0, transformOrigin: "top" });

        const tl = gsap.timeline({
          defaults: { overwrite: "auto" },
          scrollTrigger: {
            trigger: section,
            start: "top top",
            end: "bottom bottom",
            scrub: 1,
            pin: pin,
            anticipatePin: 1,
            invalidateOnRefresh: true,
            pinSpacing: true,
          },
        });

        tl.to(heading, {
          autoAlpha: 0,
          y: -30,
          duration: 1,
          ease: "power2.inOut",
        }, 0);

        tl.to(lineInner, {
          scaleY: 1,
          duration: 8,
          ease: "none",
        }, 0.5);

        const revealAt = [1.2, 3.4, 5.6, 7.8];

        reasons.forEach((reason, i) => {
          const dir = reason.side === "left" ? -28 : 28;

          tl.to(
            nodes[i],
            {
              scale: 1,
              autoAlpha: 1,
              duration: 0.5,
              ease: "back.out(2.2)",
            },
            revealAt[i]
          );

          tl.to(
            cards[i],
            {
              autoAlpha: 1,
              y: 0,
              rotateY: 0,
              scale: 1,
              duration: 0.8,
              ease: "power3.out",
            },
            revealAt[i]
          ).from(
            cards[i],
            {
              rotateY: dir,
              duration: 0.8,
              ease: "power3.out",
            },
            revealAt[i]
          );
        });

        requestAnimationFrame(() => ScrollTrigger.refresh());
      });

      /* ============================================================
         AMBIENT CURSOR SPOTLIGHT
      ============================================================ */
      const spotlight = spotlightRef.current;
      let raf = 0;
      let px = 50;
      let py = 40;

      const onMove = (e: PointerEvent) => {
        const rect = section.getBoundingClientRect();
        const nx = ((e.clientX - rect.left) / rect.width) * 100;
        const ny = ((e.clientY - rect.top) / rect.height) * 100;
        cancelAnimationFrame(raf);
        raf = requestAnimationFrame(() => {
          px = nx;
          py = ny;
          if (spotlight) {
            spotlight.style.setProperty("--mx", `${px}%`);
            spotlight.style.setProperty("--my", `${py}%`);
          }
        });
      };

      section.addEventListener("pointermove", onMove);

      return () => {
        section.removeEventListener("pointermove", onMove);
        cancelAnimationFrame(raf);
      };
    }, section);

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={sectionRef}
      id="why-us"
      className="relative w-full max-w-full overflow-x-clip bg-black lg:h-[320vh]"
    >
      {/* ambient nebula wash */}
      <div
        className="pointer-events-none absolute inset-0 opacity-70"
        style={{
          background:
            "radial-gradient(60% 45% at 18% 15%, rgba(110,140,255,0.16), transparent 60%), radial-gradient(55% 40% at 85% 80%, rgba(79,224,176,0.14), transparent 60%)",
        }}
      />

      {/* cursor spotlight */}
      <div
        ref={spotlightRef}
        className="pointer-events-none absolute inset-0 z-[1] transition-opacity duration-500"
        style={
          {
            "--mx": "50%",
            "--my": "40%",
            background:
              "radial-gradient(420px circle at var(--mx) var(--my), rgba(120,140,255,0.10), transparent 70%)",
          } as React.CSSProperties
        }
      />

      {/* particle field */}
      <div className="pointer-events-none absolute inset-0 z-[1] overflow-hidden">
        {particles.map((p, i) => (
          <span
            key={i}
            className="wcu-particle absolute rounded-full bg-white"
            style={{
              left: `${p.x}%`,
              top: `${p.y}%`,
              width: `${p.size}px`,
              height: `${p.size}px`,
              animationDelay: `${p.delay}s`,
              animationDuration: `${p.duration}s`,
            }}
          />
        ))}
      </div>

      {/* faint grid */}
      <div
        className="pointer-events-none absolute inset-0 z-[1] opacity-[0.06]"
        style={{
          backgroundImage:
            "linear-gradient(rgba(255,255,255,0.6) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.6) 1px, transparent 1px)",
          backgroundSize: "64px 64px",
        }}
      />

      {/* ================= DESKTOP PINNED VIEWPORT ================= */}
      <div
        ref={pinRef}
        className="relative z-10 hidden h-screen w-full max-w-full overflow-hidden lg:block"
      >
        {/* heading */}
        <div
          ref={headingRef}
          className="absolute left-1/2 top-[7%] w-full max-w-[720px] -translate-x-1/2 px-6 text-center"
        >
          <h2 className="text-[clamp(2.4rem,4.4vw,3.4rem)] font-medium leading-[1.05] tracking-[-0.04em] text-white">
            The intelligence layer for teams who move fast
          </h2>
          <p className="mx-auto mt-5 max-w-[480px] text-sm leading-7 text-white/55 md:text-base">
            Four reasons teams choose Mentroid to build the systems that run their business.
          </p>
        </div>

        {/* thread */}
        <div className="absolute left-1/2 top-0 h-full w-px -translate-x-1/2 overflow-hidden">
          <div className="h-full w-full bg-white/10" />
          <div
            ref={lineInnerRef}
            className="absolute inset-0 w-full"
            style={{
              background:
                "linear-gradient(to bottom, #6E8CFF, #9B7CFF, #57D6E0, #4FE0B0)",
              boxShadow: "0 0 18px 1px rgba(120,150,255,0.55)",
            }}
          />
        </div>

        {/* nodes + cards */}
        {reasons.map((reason, i) => {
          const Icon = reason.icon;
          const isRight = reason.side === "right";
          return (
            <div key={reason.title}>
              <div
                ref={(el) => {
                  nodeRefs.current[i] = el;
                }}
                className="absolute left-1/2 z-20 h-3 w-3 -translate-x-1/2 -translate-y-1/2 rounded-full"
                style={{
                  top: `${reason.top}%`,
                  background: reason.accent,
                  boxShadow: `0 0 16px 3px ${reason.accent}99`,
                }}
              />

              <div
                className="absolute h-px"
                style={{
                  top: `${reason.top}%`,
                  left: isRight ? "50%" : undefined,
                  right: isRight ? undefined : "50%",
                  width: "6%",
                  background: `linear-gradient(${isRight ? "90deg" : "270deg"}, ${reason.accent}, transparent)`,
                }}
              />

              <div
                ref={(el) => {
                  cardRefs.current[i] = el;
                }}
                className="group absolute w-[32%] -translate-y-1/2 rounded-2xl border border-white/10 p-6 backdrop-blur-xl transition-transform duration-500 hover:-translate-y-[calc(50%+4px)]"
                style={{
                  top: `${reason.top}%`,
                  left: isRight ? "57%" : undefined,
                  right: isRight ? undefined : "57%",
                  background:
                    "linear-gradient(160deg, rgba(255,255,255,0.07), rgba(255,255,255,0.02))",
                  transformStyle: "preserve-3d",
                  perspective: "800px",
                }}
              >
                <div
                  className="pointer-events-none absolute inset-0 rounded-2xl opacity-0 transition-opacity duration-500 group-hover:opacity-100"
                  style={{
                    boxShadow: `0 0 30px 2px ${reason.accent}33, inset 0 0 0 1px ${reason.accent}44`,
                  }}
                />
                <div
                  className="mb-4 flex h-10 w-10 items-center justify-center rounded-full"
                  style={{
                    background: `${reason.accent}1a`,
                    boxShadow: `0 0 14px 1px ${reason.accent}55`,
                  }}
                >
                  <Icon size={18} color={reason.accent} strokeWidth={1.8} />
                </div>
                <h3 className="text-lg font-medium tracking-[-0.02em] text-white">
                  {reason.title}
                </h3>
                <p className="mt-2.5 text-sm leading-6 text-white/60">
                  {reason.description}
                </p>
              </div>
            </div>
          );
        })}
      </div>

      {/* ================= MOBILE / TABLET STACK ================= */}
      <div className="relative z-10 w-full max-w-full px-6 py-24 sm:px-10 lg:hidden">
        <div className="mx-auto max-w-[560px] text-center">
          <h2 className="text-[clamp(2rem,7vw,2.6rem)] font-medium leading-[1.08] tracking-[-0.03em] text-white">
            The intelligence layer for teams who move fast
          </h2>
          <p className="mx-auto mt-4 max-w-[420px] text-sm leading-7 text-white/55">
            Four reasons teams choose Mentroid to build the systems that run their business.
          </p>
        </div>

        <div className="wcu-mobile-track relative mx-auto mt-16 max-w-[440px]">
          <div className="absolute left-4 top-0 h-full w-px bg-white/10" />
          <div className="absolute left-4 top-0 h-full w-px overflow-hidden">
            <div
              className="wcu-mobile-track-fill h-full w-full"
              style={{
                background:
                  "linear-gradient(to bottom, #6E8CFF, #9B7CFF, #57D6E0, #4FE0B0)",
                boxShadow: "0 0 14px 1px rgba(120,150,255,0.5)",
                transformOrigin: "top",
              }}
            />
          </div>

          <div className="flex flex-col gap-10">
            {reasons.map((reason, i) => {
              const Icon = reason.icon;
              return (
                <div key={reason.title} className="relative pl-12">
                  <div
                    className="absolute left-4 top-6 h-2.5 w-2.5 -translate-x-1/2 rounded-full"
                    style={{
                      background: reason.accent,
                      boxShadow: `0 0 12px 2px ${reason.accent}99`,
                    }}
                  />
                  <div
                    ref={(el) => {
                      mobileCardRefs.current[i] = el;
                    }}
                    className="rounded-2xl border border-white/10 p-5 backdrop-blur-xl active:scale-[0.99]"
                    style={{
                      background:
                        "linear-gradient(160deg, rgba(255,255,255,0.07), rgba(255,255,255,0.02))",
                    }}
                  >
                    <div
                      className="mb-3.5 flex h-9 w-9 items-center justify-center rounded-full"
                      style={{
                        background: `${reason.accent}1a`,
                        boxShadow: `0 0 12px 1px ${reason.accent}55`,
                      }}
                    >
                      <Icon size={17} color={reason.accent} strokeWidth={1.8} />
                    </div>
                    <h3 className="text-base font-medium tracking-[-0.02em] text-white">
                      {reason.title}
                    </h3>
                    <p className="mt-2 text-sm leading-6 text-white/60">
                      {reason.description}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <style jsx>{`
        .wcu-particle {
          opacity: 0;
          animation-name: wcuTwinkle;
          animation-iteration-count: infinite;
          animation-timing-function: ease-in-out;
          box-shadow: 0 0 6px 1px rgba(160, 180, 255, 0.6);
        }
        @keyframes wcuTwinkle {
          0% {
            opacity: 0;
            transform: translateY(0px);
          }
          50% {
            opacity: 0.65;
            transform: translateY(-10px);
          }
          100% {
            opacity: 0;
            transform: translateY(-20px);
          }
        }
        @media (prefers-reduced-motion: reduce) {
          .wcu-particle {
            animation: none;
            opacity: 0.25;
          }
        }
      `}</style>
    </section>
  );
}